    ((280, 300), SKIN),         # his leg, stretched out in front of him
    ((301, 204), SLAB),         # the slab's edge beside it
    ((400, 125), HAIR_GIRL),    # her hair
    ((463, 240), SKIN_G),       # her far arm, down past her shoulder
    ((348, 192), SKIN_G),       # her ear
