def _disc(cx, cy, rx, ry, sides=22):
    """A closed outline of a circle or ellipse, as anchor tuples."""
    return [(cx + rx * math.cos(i * math.tau / sides),
             cy + ry * math.sin(i * math.tau / sides), None, None)
            for i in range(sides)]


# =======================================================================
# The field
# =======================================================================


def _rand(seed, salt=0):
    """Deterministic 0..1: the same field, and the same flowers, every time."""
    n = (seed * 1103515245 + salt * 12345 + 1013904223) & 0x7FFFFFFF
    n ^= (n >> 13)
    n = (n * 1274126177) & 0x7FFFFFFF
    return ((n >> 7) & 0xFFFF) / 65535.0


def _hedge():
    """The far treeline: one wavy band on the horizon, and nothing behind it."""
    pts = []
    x = -10.0
    i = 0
    while x < ART_W + 10.0:
        bump = 5.0 + 12.0 * _rand(i, 3)
        pts.append((x, HORIZON - bump, None, None))
        x += 16.0 + 22.0 * _rand(i, 7)
        i += 1
    pts.append((ART_W + 10.0, HORIZON + 12.0, None, None))
    pts.append((-10.0, HORIZON + 12.0, None, None))
    return pts


def _blade(x, y, w, h, lean):
    """A blade of grass: a curved spike, leaning. Three anchors and two handles.

    An earlier version of this was a plain triangle, which at this size read
    unmistakably as a small fir tree — a field of them looked like a plantation.
    The curve is what makes it grass.
    """
    return [(x - w, y, None, (lean * 0.10, -h * 0.34)),
            (x + lean, y - h, (-lean * 0.34, h * 0.40),
             (lean * 0.16, -h * 0.04)),
            (x + w, y, (lean * 0.10, -h * 0.30), None)]


def _meadow(y0, y1, count, seed, small, large, colour, ceiling=None):
    """A band of grass between two heights, taller and broader as it nears.

    `ceiling` is the highest a blade may reach whatever its own height would
    be — which is how the grass in front of the aeroplane is kept off it.
    """
    out = []
    for i in range(count):
        t = _rand(i, seed)
        u = _rand(i, seed + 101)
        y = y0 + (y1 - y0) * (u ** 0.7)
        near = (y - y0) / max(1.0, y1 - y0)
        h = small + (large - small) * (0.45 + 0.55 * near) * (0.6 + 0.8 * t)
        if ceiling is not None:
            h = min(h, max(0.0, y - ceiling))
        lean = (_rand(i, seed + 211) - 0.5) * h * 0.62
        out.append((_blade(t * (ART_W + 40.0) - 20.0, y, h * 0.11, h, lean),
                    colour))
    return out


# =======================================================================
# The node
# =======================================================================


def _vec(x, y):
    return dex.Vector.new(float(x), float(y))


class DynabookField:
    """The whole scene, painted to fit whatever box it is given.

    The trace is parsed and coloured once — on the first frame rather than in
    `__init__`, so a node that is never drawn never pays for it.
    """

    def __init__(self):
        self._kids = None

    # -- painting ---------------------------------------------------------

    def _path(self, anchors, s, fill=None, stroke=None, width=0.0,
              dx=0.0, dy=0.0, closed=True):
        """A `dex.Path` from `(x, y, in, out)` anchors, offset then scaled."""
        built = []
        for (x, y, ih, oh) in anchors:
            a = dex.Anchor.corner(_vec((x + dx) * s, (y + dy) * s))
            if ih is not None:
                a.in_handle = _vec(ih[0] * s, ih[1] * s)
            if oh is not None:
                a.out_handle = _vec(oh[0] * s, oh[1] * s)
            built.append(a)
        fill_c = dex.Color.rgb(*fill) if fill else dex.Color.transparent()
        stroke_s = (dex.Stroke.new(width * s, dex.Color.rgb(*stroke))
                    if stroke else dex.Stroke.none())
        path = dex.Path.polygon([_vec(0, 0)], fill_c, stroke_s)
        path.anchors = built
        path.closed = closed
        return path

    def _flat_quad(self, x0, y0, x1, y1):
        return [(x0, y0, None, None), (x1, y0, None, None),
                (x1, y1, None, None), (x0, y1, None, None)]

    def _ramp(self, ctx, box, s, x0, y0, x1, y1, near, far):
        """A rectangle graded from `near` at the top to `far` at the bottom.

        The only graded things in the picture are the sky and the field, which
        are distance rather than objects. 270 degrees runs bottom to top.
        """
        path = self._path(self._flat_quad(x0, y0, x1, y1), s, fill=far)
        path.fill_mode = dex.FillMode.linear()
        path.fill_end = dex.Color.rgb(*near)
        path.fill_angle = 270.0
        ctx.draw_node(path, box)

    def _ink(self, ctx, box, s, anchors, fill, width=PEN, closed=True):
        ctx.draw_node(self._path(anchors, s, fill=fill, stroke=INK,
                                 width=width, closed=closed), box)

    # -- the picture ------------------------------------------------------

    def _sky(self, ctx, box, s):
        self._ramp(ctx, box, s, -2, -2, ART_W + 2, HORIZON + 14,
                   SKY_HIGH, SKY_LOW)
        # Three flat clouds, high and out of the way of the plane.
        for (cx, cy, r) in ((132, 68, 30), (196, 74, 20), (700, 52, 26),
                            (756, 60, 18), (438, 40, 17)):
            ctx.draw_node(self._path(_disc(cx, cy, r * 1.5, r), s, fill=CLOUD),
                          box)
        for (cx, cy, r) in ((150, 84, 34), (712, 68, 30), (444, 52, 20)):
            ctx.draw_node(
                self._path(_disc(cx, cy, r * 1.6, r * 0.5), s, fill=CLOUD_LOW),
                box)

    def _field(self, ctx, box, s):
        ctx.draw_node(self._path(_hedge(), s, fill=HEDGE), box)
        self._ramp(ctx, box, s, -2, HORIZON + 8, ART_W + 2, ART_H + 2,
                   FIELD_FAR, FIELD_NEAR)
        # A second, nearer hedge line, lower and lighter: two bands of green
        # a shade apart are what read as a field going away.
        band = [(x, y + 26.0, ih, oh) for (x, y, ih, oh) in _hedge()]
        ctx.draw_node(self._path(band, s, fill=HEDGE_LIT), box)

    def _plane(self, ctx, box, s):
        """Back to front: the far wing's shadow on the grass, then the tail
        group, then the fuselage, then everything that sits on top of it."""
        ctx.draw_node(
            self._path(_disc(430, 328, 340, 20), s, fill=SHADOW), box)

        self._ink(ctx, box, s, FIN, BODY)
        self._ink(ctx, box, s, TAILPLANE, BODY_LOW)

        # The tailwheel, right at the back, all but sitting in the grass.
        self._ink(ctx, box, s, _disc(768, 328, 15, 15), TYRE, width=PEN * 0.6)

        self._ink(ctx, box, s, FUSELAGE, BODY)
        ctx.draw_node(self._path(BELLY, s, fill=CREAM), box)
        ctx.draw_node(self._path(STRIPE, s, fill=TRIM), box)

        self._ink(ctx, box, s, WINDSCREEN, GLASS, width=PEN * 0.75)
        self._ink(ctx, box, s, WINDOW, GLASS, width=PEN * 0.75)
        ctx.draw_node(
            self._path([(176, 236, None, None), (212, 222, None, None),
                        (224, 226, None, None), (188, 242, None, None)],
                       s, fill=GLASS_LIT), box)
        self._ink(ctx, box, s, DOOR, None, width=PEN * 0.55)

        # The main wheel, forward and to the left of the boy, where it can be
        # seen — it is what says the aeroplane is standing on the ground.
        self._ink(ctx, box, s, _disc(214, 344, 34, 34), TYRE, width=PEN * 0.7)
        ctx.draw_node(self._path(_disc(214, 344, 14, 14), s, fill=CREAM), box)
        self._ink(ctx, box, s,
                  [(178, 300, None, None), (206, 296, None, None),
                   (222, 342, None, None), (200, 344, None, None)],
                  METAL, width=PEN * 0.5)

        self._ink(ctx, box, s, COWL, BODY_LOW)
        ctx.draw_node(
            self._path([(92, 300, None, (10, 4)), (140, 306, (-14, -2), None),
                        (140, 320, None, (-14, 2)), (92, 314, (10, -2), None)],
                       s, fill=METAL), box)
        self._ink(ctx, box, s, BLADE_UP, METAL, width=PEN * 0.65)
        self._ink(ctx, box, s, BLADE_DOWN, METAL, width=PEN * 0.65)
        self._ink(ctx, box, s, _disc(68, 282, 20, 23), TRIM, width=PEN * 0.7)

        # The wing last: it is the nearest thing on the aeroplane and crosses
        # in front of the cabin, the fin and both children's heads.
        for strut in STRUTS:
            self._ink(ctx, box, s, strut, METAL, width=PEN * 0.5)
        self._ink(ctx, box, s, WING, BODY)

    def _kids_layer(self, ctx, box, s):
        if self._kids is None:
            self._kids = _kid_layers()
        for (anchors, colour) in self._kids:
            built = []
            for (x, y, hin, hout) in anchors:
                a = dex.Anchor.corner(_vec((x + KIDS_X) * s, (y + KIDS_Y) * s))
                if hin is not None:
                    a.in_handle = _vec(hin[0] * s, hin[1] * s)
                if hout is not None:
                    a.out_handle = _vec(hout[0] * s, hout[1] * s)
                built.append(a)
            if colour is None:
                # A gap between the two children: the field, at its own height,
                # graded exactly as the field is so the seam does not show.
                ys = [y + KIDS_Y for (_x, y, _i, _o) in anchors]
                near = _field_colour(min(ys))
                far = _field_colour(max(ys))
                path = dex.Path.polygon([_vec(0, 0)],
                                        dex.Color.rgb(*[int(c) for c in far]),
                                        dex.Stroke.none())
                path.fill_mode = dex.FillMode.linear()
                path.fill_end = dex.Color.rgb(*[int(c) for c in near])
                path.fill_angle = 270.0
            else:
                path = dex.Path.polygon([_vec(0, 0)], dex.Color.rgb(*colour),
                                        dex.Stroke.none())
            path.anchors = built
            path.closed = True
            ctx.draw_node(path, box)

    def _grass_front(self, ctx, box, s):
        """The blades in front of the children, so they sit *in* the field.

        Blades only. An earlier version filled a band behind them as well, to
        bury what was left of Kay's ink tufts; with the tufts properly cut out
        there is nothing to bury, and the band only ever read as a terrace laid
        across the picture — first with a smooth edge, then with a cut one.

        They start below the children's own bottom edge and are short enough
        that none of them reaches a screen. Grass in front of a machine lying in
        a field is right; grass sprouting out of the middle of one is not.
        """
        for (tuft, colour) in _meadow(GRASS_LINE + 4, ART_H + 6, 46, 11,
                                      14.0, 30.0, GRASS_DARK):
            ctx.draw_node(self._path(tuft, s, fill=colour), box)
        for (tuft, colour) in _meadow(GRASS_LINE + 16, ART_H + 6, 32, 23,
                                      12.0, 26.0, GRASS_LIT):
            ctx.draw_node(self._path(tuft, s, fill=colour), box)
        for i in range(24):
            x = _rand(i, 41) * (ART_W + 30.0) - 15.0
            y = GRASS_LINE + 14.0 + _rand(i, 57) ** 0.7 * (ART_H - GRASS_LINE)
            r = 2.2 + 2.6 * (y - GRASS_LINE) / (ART_H - GRASS_LINE)
            colour = FLOWER if _rand(i, 73) > 0.28 else FLOWER_WHITE
            ctx.draw_node(self._path(_disc(x, y, r, r, 9), s, fill=colour), box)

    # -- what is on the screens -------------------------------------------

    def _uv(self, quad, u, v, _c=lambda t: min(0.995, max(0.005, t))):
        """A point in a screen's own square, mapped onto its four corners.

        Both screens are seen at an angle, so content is authored square and
        put through the corners rather than drawn in place. Nothing can leave
        the screen it is drawn on — the square is clamped first, and a rotated
        quad would otherwise need real clipping.
        """
        (tl, tr, br, bl) = quad
        (u, v) = (_c(u), _c(v))
        tx = tl[0] + (tr[0] - tl[0]) * u
        ty = tl[1] + (tr[1] - tl[1]) * u
        bx = bl[0] + (br[0] - bl[0]) * u
        by = bl[1] + (br[1] - bl[1]) * u
        return (tx + (bx - tx) * v + KIDS_X, ty + (by - ty) * v + KIDS_Y)

    def _blob(self, quad, cu, cv, ru, rv, sides=16):
        return [self._uv(quad, cu + ru * math.cos(i * math.tau / sides),
                         cv + rv * math.sin(i * math.tau / sides)) + (None, None)
                for i in range(sides)]

    def _quad(self, quad, corners):
        return [self._uv(quad, u, v) + (None, None) for (u, v) in corners]

    def _helix(self, quad, t0, t1, steps=15, half=None):
        """One stretch of the ribbon, as a band of constant width.

        A centre line runs along the axis and swings either side of it on a
        sine; the band is that line given thickness *along* the axis, which is
        what makes a flat shape read as something wound round one.
        """
        half = HELIX_HALF if half is None else half
        (ax, ay) = HELIX_A
        (bx, by) = HELIX_B
        (dx, dy) = (bx - ax, by - ay)
        length = math.hypot(dx, dy)
        (nx, ny) = (dx / length, dy / length)
        (px, py) = (-ny, nx)
        (near, far) = ([], [])
        for i in range(steps + 1):
            t = t0 + (t1 - t0) * i / steps
            swing = math.sin(t * math.tau * HELIX_TURNS) * HELIX_AMP
            (cx, cy) = (ax + dx * t + px * swing, ay + dy * t + py * swing)
            near.append((cx + nx * half, cy + ny * half))
            far.append((cx - nx * half, cy - ny * half))
        return [self._uv(quad, u, v) + (None, None)
                for (u, v) in near + far[::-1]]

    def _arrow(self, quad, a, b, half, head):
        """A strand drawn as an arrow: the other half of a ribbon diagram.

        An arrow is what makes the picture legible as a protein rather than as
        a spring. Two of them either side of the helix, pointing the way the
        chain runs, and the thing reads at the size it is actually drawn.
        """
        (ax, av) = a
        (bx, bv) = b
        (dx, dv) = (bx - ax, bv - av)
        length = math.hypot(dx, dv)
        (nx, nv) = (dx / length, dv / length)
        (px, pv) = (-nv, nx)
        (sx, sv) = (bx - nx * head, bv - nv * head)
        pts = [(ax + px * half, av + pv * half),
               (sx + px * half, sv + pv * half),
               (sx + px * half * 2.1, sv + pv * half * 2.1),
               (bx, bv),
               (sx - px * half * 2.1, sv - pv * half * 2.1),
               (sx - px * half, sv - pv * half),
               (ax - px * half, av - pv * half)]
        return [self._uv(quad, u, v) + (None, None) for (u, v) in pts]

    def _boy_screen(self, ctx, box, s):
        """A protein, as a ribbon diagram: two strands and the helix between.

        The whole ribbon goes down dark, and the half of each turn facing us is
        painted over it bright, with a darker band under each to draw its edge.
        That alternation is the whole of the illusion, and it is what a ribbon
        diagram is doing too. Two versions did not read: turns drawn as separate
        blobs looked like beads on a wire, and the helix alone looked like a
        spring. The arrows are what say protein — but only once they were moved
        out of the corridor the helix sweeps, where they had run together with
        it into one unreadable shape.
        """
        q = BOY_SCREEN
        ctx.draw_node(self._path(self._quad(q, ((0, 0), (1, 0), (1, 1), (0, 1))),
                                 s, fill=SCREEN_BG), box)
        for i in range(1, 5):
            v = i / 5.0
            ctx.draw_node(self._path(
                self._quad(q, ((0, v - 0.0025), (1, v - 0.0025),
                               (1, v + 0.0025), (0, v + 0.0025))),
                s, fill=SCREEN_GRID), box)

        # The two beta strands. The helix sweeps a wide corridor up the middle
        # of the screen, so they go in the corners it leaves — above it and
        # below it — pointing the way the chain runs. Laid across that corridor
        # instead, all three ran together into one shape.
        for (a, b) in (((0.05, 0.40), (0.33, 0.10)),
                       ((0.67, 0.93), (0.95, 0.63))):
            ctx.draw_node(self._path(self._arrow(q, a, b, 0.058, 0.14), s,
                                     fill=SHEET_EDGE), box)
            ctx.draw_node(self._path(self._arrow(q, a, b, 0.040, 0.125), s,
                                     fill=SHEET), box)

        ctx.draw_node(self._path(self._helix(q, 0.0, 1.0, 48,
                                             HELIX_HALF * 1.18), s,
                                 fill=HELIX_EDGE), box)
        ctx.draw_node(self._path(self._helix(q, 0.0, 1.0, 48), s,
                                 fill=HELIX_BACK), box)
        for k in range(HELIX_TURNS):
            (a, b) = (k / HELIX_TURNS, (k + 0.5) / HELIX_TURNS)
            ctx.draw_node(self._path(self._helix(q, a, b, 14,
                                                 HELIX_HALF * 1.16), s,
                                     fill=HELIX_EDGE), box)
            ctx.draw_node(self._path(self._helix(q, a, b, 14), s,
                                     fill=HELIX_FRONT), box)

    def _girl_screen(self, ctx, box, s):
        """A cell, seen flat on: membrane, nucleus, mitochondria, vesicles.

        Her machine lies almost level in her lap, so the screen is a shallow
        band and everything on it is squashed to a third of its height. What
        survives that is roundness and colour, so each part is drawn as a ring
        of its own edge colour with a lighter one inside — a membrane reads at
        this size, a cristae does not.
        """
        q = GIRL_SCREEN
        ctx.draw_node(self._path(self._quad(q, ((0, 0), (1, 0), (1, 1), (0, 1))),
                                 s, fill=SCREEN_BG), box)

        ctx.draw_node(self._path(self._blob(q, 0.5, 0.5, 0.48, 0.47, 24),
                                 s, fill=CELL_EDGE), box)
        ctx.draw_node(self._path(self._blob(q, 0.5, 0.5, 0.445, 0.42, 24),
                                 s, fill=CELL_WALL), box)
        ctx.draw_node(self._path(self._blob(q, 0.5, 0.5, 0.40, 0.35, 24),
                                 s, fill=CELL_BODY), box)

        # The nucleus, off to one side, with its envelope and a nucleolus.
        ctx.draw_node(self._path(self._blob(q, 0.35, 0.5, 0.20, 0.23, 16),
                                 s, fill=NUCLEUS_EDGE), box)
        ctx.draw_node(self._path(self._blob(q, 0.35, 0.5, 0.175, 0.195, 16),
                                 s, fill=NUCLEUS), box)
        ctx.draw_node(self._path(self._blob(q, 0.33, 0.52, 0.07, 0.085, 10),
                                 s, fill=NUCLEOLUS), box)

        # Two mitochondria, and the small stuff.
        for (cu, cv, ru, rv) in ((0.68, 0.30, 0.105, 0.075),
                                 (0.72, 0.68, 0.090, 0.065)):
            ctx.draw_node(self._path(self._blob(q, cu, cv, ru, rv, 12),
                                     s, fill=MITO_EDGE), box)
            ctx.draw_node(self._path(self._blob(q, cu, cv, ru * 0.7, rv * 0.62,
                                                12), s, fill=MITO), box)
        for (cu, cv, ru) in ((0.58, 0.52, 0.045), (0.20, 0.24, 0.038),
                             (0.84, 0.48, 0.036)):
            ctx.draw_node(self._path(self._blob(q, cu, cv, ru, ru * 0.9, 10),
                                     s, fill=ORGANELLE), box)
        for (cu, cv) in ((0.48, 0.20), (0.26, 0.76), (0.62, 0.82)):
            ctx.draw_node(self._path(self._blob(q, cu, cv, 0.028, 0.026, 8),
                                     s, fill=VESICLE), box)

    # -- fitting ----------------------------------------------------------

    def draw(self, ctx):
        origin = ctx.constraints.pos
        avail = ctx.constraints.available()
        (w, h) = (avail.x, avail.y)
        if not (math.isfinite(w) and math.isfinite(h)) or w <= 0.0 or h <= 0.0:
            (w, h) = (ART_W, ART_H)
        s = min(w / ART_W, h / ART_H)
        dx = (w - ART_W * s) / 2.0
        dy = (h - ART_H * s) / 2.0

        # The box is the picture, not the room it was given: an image does not
        # paint out into its own letterboxing.
        box = dex.DrawConstraints(
            pos=dex.ScreenPos.new(origin.x + dx, origin.y + dy),
            x=dex.AxisConstraint.Exactly(ART_W * s),
            y=dex.AxisConstraint.Exactly(ART_H * s),
            wrap=None,
            should_clip=True,
        )

        self._sky(ctx, box, s)
        self._field(ctx, box, s)
        self._plane(ctx, box, s)
        # The field: over the aeroplane's wheels, and *behind* the children so
        # it textures the ground either side of them without sprouting out of a
        # shoulder. One band rather than two — a separate short one at the
        # belly only ever grew up the fuselage.
        for (tuft, colour) in _meadow(PLANE_GRASS + 2, ART_H + 6, 118, 43,
                                      10.0, 32.0, GRASS_DARK,
                                      ceiling=PLANE_GRASS):
            ctx.draw_node(self._path(tuft, s, fill=colour), box)
        self._kids_layer(ctx, box, s)
        self._grass_front(ctx, box, s)
        self._boy_screen(ctx, box, s)
        self._girl_screen(ctx, box, s)

        return dex.DrawResult.Complete(
            region=dex.ScreenRegion.from_min_size(origin, dex.Vector.new(w, h))
        )

    def type_name(self):
        return "The Dynabook, in a field"


def transform():
    """Kay's two children with their Dynabooks, out in a field with a plane."""
    return DynabookField()
